         }
+      case 'misuseBreaker':
+        // The tool-misuse circuit breaker kill switch (gh-1572): mirrors
+        // `_parseAgentMisuseBreakerValue` in cli_config.dart — a boolean,
+        // `false` persisted, the `true` default never written.
+        if (entry.value is! bool) {
