Future<void> _mcpDeleteAction(String path, String name) async {
  final sure = (await _askLine("remove server '$name'? (y/N): "))?.trim();
  if (sure?.toLowerCase() != 'y') return;
  await _mcpWriteFresh(
    path,
    name,
    expectPresent: true,
