    /// `_dropAutoUpdateKey` lands it: the key line removed, everything
    /// else byte-for-byte.
    Future<void> dropAutoUpdateKeyWrite() async {
      final path = configFile(tmp).path;
      final edited = removeYamlPath(
        (await env.readTextFile(path)).getOrThrow(),
        const ['auto_update'],
