/// dedupe); null when the list is null or the rule is gone.
TtsrRule? _ttsrFindRule(List<TtsrRule>? rules, String name) {
  if (rules == null) return null;
  TtsrRule? found;
  for (final candidate in rules) {
    if (candidate.name == name) found = candidate;
  }
  return found;
}

