  Map<String, Object> _readsTurnChunk() => {
    'id': 'chatcmpl-x',
    'object': 'chat.completion.chunk',
    'choices': [
      {
        'index': 0,
        'delta': {
          'role': 'assistant',
          'tool_calls': [
            for (var i = 1; i <= 8; i++)
              {
                'index': i - 1,
                'id': 'call_$i',
                'type': 'function',
                'function': {
                  'name': 'read',
                  'arguments': '{"path": "big$i.txt"}',
                },
              },
          ],
        },
        'finish_reason': null,
      },
    ],
