      // (`_upsertConfigYaml`). Every sanctioned user-file write must
      // fire the hook exactly once.
      var resyncs = 0;
      final (cli, _) = bootCli(onUserConfigFileChanged: () async => resyncs++);
      configFile(tmp)
        ..createSync(recursive: true)
